#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> p, sz;
    DSU(int n) : p(n + 1), sz(n + 1, 1) {
        iota(p.begin(), p.end(), 0);
    }
    int find(int x) {
        while (p[x] != x) {
            p[x] = p[p[x]];
            x = p[x];
        }
        return x;
    }
    void unite(int a, int b) {
        a = find(a);
        b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    DSU dsu(N);
    vector<vector<int>> adj(N + 1);

    for (int i = 0; i < M; i++) {
        int x, y;
        cin >> x >> y;
        dsu.unite(x, y);
        adj[x].push_back(y);
        adj[y].push_back(x);
    }

    vector<int> compSize(N + 1, 0);
    for (int i = 1; i <= N; i++) {
        compSize[dsu.find(i)]++;
    }

    vector<char> mark(N + 1, 0);

    for (int v = 1; v <= N; v++) {
        int r = dsu.find(v);
        if ((int)adj[v].size() < compSize[r] - 1) {
            for (int u : adj[v]) {
                mark[u] = 1;
            }

            for (int u = 1; u <= N; u++) {
                if (u != v && dsu.find(u) == r && !mark[u]) {
                    cout << v << ' ' << u << '\n';
                    return 0;
                }
            }
        }
    }

    cout << -1 << '\n';
    return 0;
}
